// SUPPLIED: configuration guard. You call parseConfig from src/api.ts; you do not edit this file.
//
// parseConfig checks untrusted JSON from the game-data API in two stages:
//   1. shape   - every field the rules need is present with the right type;
//   2. identity - the definition is exactly the fixed reference definition this package supports.
// It returns a new, frozen configuration object or throws ConfigError. It does not install
// arbitrary boards: a different but well-formed definition is rejected as unexpected.
//
// Wire data uses `initialMoves`; your rule state uses `movesRemaining` (see GAME-CONTRACT.md).

export type Genre = "treasure" | "range";

export interface Point {
  readonly x: number;
  readonly y: number;
}

export interface Treasure extends Point {
  readonly id: string;
  readonly value: number;
}

/** Validated treasure-hunt board (GET /api/boards/reference). */
export interface TreasureConfig {
  readonly id: string;
  readonly name: string;
  readonly width: number;
  readonly height: number;
  readonly start: Point;
  readonly walls: readonly Point[];
  readonly treasures: readonly Treasure[];
  readonly exit: Point;
  readonly initialMoves: number;
}

/** Validated target-range definition (GET /api/ranges/reference). */
export interface RangeConfig {
  readonly id: string;
  readonly name: string;
  readonly ammunition: number;
}

/** The configuration type for a genre: ConfigFor<"treasure"> is TreasureConfig. */
export type ConfigFor<G extends Genre> = G extends "treasure" ? TreasureConfig : RangeConfig;

export class ConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ConfigError";
  }
}

// The only definitions this package accepts (byte-for-byte the shared fixtures).
const REFERENCE_BOARD: TreasureConfig = {
  id: "reference",
  name: "Reference treasure hunt",
  width: 3,
  height: 3,
  start: { x: 0, y: 0 },
  walls: [{ x: 1, y: 1 }],
  treasures: [{ id: "t1", x: 2, y: 0, value: 10 }],
  exit: { x: 2, y: 2 },
  initialMoves: 6,
};

const REFERENCE_RANGE: RangeConfig = { id: "reference", name: "Reference target range", ammunition: 2 };

type Json = Record<string, unknown>;

function isRecord(value: unknown): value is Json {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function field(data: Json, name: string): unknown {
  if (!(name in data)) throw new ConfigError(`Game data has the wrong shape: missing "${name}"`);
  return data[name];
}

function text(data: Json, name: string): string {
  const value = field(data, name);
  if (typeof value !== "string") throw new ConfigError(`Game data has the wrong shape: "${name}" must be text`);
  return value;
}

function whole(data: Json, name: string): number {
  const value = field(data, name);
  if (typeof value !== "number" || !Number.isInteger(value) || value < 0) {
    throw new ConfigError(`Game data has the wrong shape: "${name}" must be a whole number`);
  }
  return value;
}

function point(value: unknown, name: string): Point {
  if (!isRecord(value)) throw new ConfigError(`Game data has the wrong shape: "${name}" must be an {x, y} object`);
  return Object.freeze({ x: whole(value, "x"), y: whole(value, "y") });
}

function list(data: Json, name: string): unknown[] {
  const value = field(data, name);
  if (!Array.isArray(value)) throw new ConfigError(`Game data has the wrong shape: "${name}" must be a list`);
  return value;
}

function parseBoard(data: Json): TreasureConfig {
  return Object.freeze({
    id: text(data, "id"),
    name: text(data, "name"),
    width: whole(data, "width"),
    height: whole(data, "height"),
    start: point(field(data, "start"), "start"),
    walls: Object.freeze(list(data, "walls").map((w) => point(w, "walls[]"))),
    treasures: Object.freeze(
      list(data, "treasures").map((t) => {
        if (!isRecord(t)) throw new ConfigError('Game data has the wrong shape: "treasures[]" must be objects');
        return Object.freeze({ id: text(t, "id"), x: whole(t, "x"), y: whole(t, "y"), value: whole(t, "value") });
      }),
    ),
    exit: point(field(data, "exit"), "exit"),
    initialMoves: whole(data, "initialMoves"),
  });
}

function parseRange(data: Json): RangeConfig {
  return Object.freeze({ id: text(data, "id"), name: text(data, "name"), ammunition: whole(data, "ammunition") });
}

/** Stable comparison of two plain JSON values (key order ignored). */
function sameJson(a: unknown, b: unknown): boolean {
  if (Array.isArray(a) && Array.isArray(b)) return a.length === b.length && a.every((v, i) => sameJson(v, b[i]));
  if (isRecord(a) && isRecord(b)) {
    const keys = Object.keys(a);
    return keys.length === Object.keys(b).length && keys.every((k) => k in b && sameJson(a[k], b[k]));
  }
  return a === b;
}

/** Validate untrusted game data for the chosen genre. Throws ConfigError on any problem. */
export function parseConfig(genre: "treasure", data: unknown): TreasureConfig;
export function parseConfig(genre: "range", data: unknown): RangeConfig;
export function parseConfig(genre: Genre, data: unknown): TreasureConfig | RangeConfig;
export function parseConfig(genre: Genre, data: unknown): TreasureConfig | RangeConfig {
  if (!isRecord(data)) throw new ConfigError("Game data has the wrong shape: expected a JSON object");
  const parsed = genre === "treasure" ? parseBoard(data) : parseRange(data);
  const reference = genre === "treasure" ? REFERENCE_BOARD : REFERENCE_RANGE;
  if (!sameJson(parsed, reference) || Object.keys(data).length !== Object.keys(reference).length) {
    throw new ConfigError("Unexpected game definition: this package supports only the fixed reference definition");
  }
  return parsed;
}
